348: /**
349:   @brief    Get the number of keys in a section of a dictionary.
350:   @param    d   Dictionary to examine
351:   @param    s   Section name of dictionary to examine
352:   @return   Number of keys in section
353:  */
354: /*--------------------------------------------------------------------------*/
355: int iniparser_getsecnkeys(const dictionary * d, const char * s)
356: {
357:     int     seclen, nkeys ;
358:     char    keym[ASCIILINESZ+1];
359:     size_t  j ;
360: 
361:     nkeys = 0;
362: 
363:     if (d==NULL) return nkeys;
364:     if (! iniparser_find_entry(d, s)) return nkeys;
365: 
366:     seclen  = (int)strlen(s);
367:     strlwc(s, keym, sizeof(keym));
368:     keym[seclen] = ':';
369: 
370:     for (j=0 ; j<d->size ; j++) {
371:         if (d->key[j]==NULL)
372:             continue ;
373:         if (!strncmp(d->key[j], keym, seclen+1))
374:             nkeys++;
375:     }
376: 
377:     return nkeys;
378: 
379: }
