614:   @param    ini     Dictionary to search
615:   @param    entry   Name of the entry to look for
616:   @return   integer 1 if entry exists, 0 otherwise
617: 
618:   Finds out if a given entry exists in the dictionary. Since sections
619:   are stored as keys with NULL associated values, this is the only way
620:   of querying for the presence of sections in a dictionary.
621:  */
622: /*--------------------------------------------------------------------------*/
623: int iniparser_find_entry(const dictionary * ini, const char * entry)
624: {
625:     int found=0 ;
626:     if (iniparser_getstring(ini, entry, INI_INVALID_KEY)!=INI_INVALID_KEY) {
627:         found = 1 ;
628:     }
629:     return found ;
630: }
