661: /**
662:   @brief    Delete an entry in a dictionary
663:   @param    ini     Dictionary to modify
664:   @param    entry   Entry to delete (entry name)
665:   @return   void
666: 
667:   If the given entry can be found, it is deleted from the dictionary.
668:  */
669: /*--------------------------------------------------------------------------*/
670: void iniparser_unset(dictionary * ini, const char * entry)
671: {
672:     char tmp_str[ASCIILINESZ+1];
673:     dictionary_unset(ini, strlwc(entry, tmp_str, sizeof(tmp_str)));
674: }
