676: static void parse_quoted_value(char *value, char quote) {
677:     char c;
678:     char *quoted;
679:     int q = 0, v = 0;
680:     int esc = 0;
681: 
682:     if(!value)
683:         return;
684: 
685:     quoted = xstrdup(value);
686: 
687:     if(!quoted) {
688:         iniparser_error_callback("iniparser: memory allocation failure\n");
689:         goto end_of_value;
690:     }
691: 
692:     while((c = quoted[q]) != '\0') {
693:         if(!esc) {
694:             if(c == '\\') {
695:                 esc = 1;
696:                 q++;
697:                 continue;
698:             }
699: 
700:             if(c == quote) {
701:                 goto end_of_value;
702:             }
703:         }
704:         esc = 0;
705:         value[v] = c;
706:         v++;
707:         q++;
708:     }
709: end_of_value:
710:     value[v] = '\0';
711:     free(quoted);
712: }
713: 
714: /*-------------------------------------------------------------------------*/
715: /**
716:   @brief    Load a single line from an INI file
717:   @param    input_line  Input line, may be concatenated multi-line input
718:   @param    section     Output space to store section
719:   @param    key         Output space to store key
720:   @param    value       Output space to store value
721:   @return   line_status value
722:  */
723: /*--------------------------------------------------------------------------*/
724: static line_status iniparser_line(
725:     const char * input_line,
726:     char * section,
727:     char * key,
728:     char * value)
729: {
730:     line_status sta ;
731:     char * line = NULL;
732:     size_t      len ;
733:     int d_quote;
734: 
735:     line = xstrdup(input_line);
736:     len = strstrip(line);
737: 
738:     sta = LINE_UNPROCESSED ;
739:     if (len<1) {
740:         /* Empty line */
741:         sta = LINE_EMPTY ;
742:     } else if (line[0]=='#' || line[0]==';') {
743:         /* Comment line */
744:         sta = LINE_COMMENT ;
745:     } else if (line[0]=='[' && line[len-1]==']') {
746:         /* Section name without opening square bracket */
747:         sscanf(line, "[%[^\n]", section);
748:         len = strlen(section);
749:         /* Section name without closing square bracket */
750:         if(section[len-1] == ']')
751:         {
752:             section[len-1] = '\0';
753:         }
754:         strstrip(section);
755:         strlwc(section, section, len);
756:         sta = LINE_SECTION ;
757:     } else if ((d_quote = sscanf (line, "%[^=] = \"%[^\n]\"", key, value)) == 2
758:                ||  sscanf (line, "%[^=] = '%[^\n]'",   key, value) == 2) {
759:         /* Usual key=value with quotes, with or without comments */
760:         strstrip(key);
761:         strlwc(key, key, len);
762:         if(d_quote == 2)
763:             parse_quoted_value(value, '"');
764:         else
765:             parse_quoted_value(value, '\'');
766:         /* Don't strip spaces from values surrounded with quotes */
767:         sta = LINE_VALUE ;
768:     } else if (sscanf (line, "%[^=] = %[^;#]", key, value) == 2) {
769:         /* Usual key=value without quotes, with or without comments */
770:         strstrip(key);
771:         strlwc(key, key, len);
772:         strstrip(value);
773:         /*
774:          * sscanf cannot handle '' or "" as empty values
775:          * this is done here
776:          */
777:         if (!strcmp(value, "\"\"") || (!strcmp(value, "''"))) {
778:             value[0]=0 ;
779:         }
780:         sta = LINE_VALUE ;
781:     } else if (sscanf(line, "%[^=] = %[;#]", key, value)==2
782:            ||  sscanf(line, "%[^=] %[=]", key, value) == 2) {
783:         /*
784:          * Special cases:
785:          * key=
786:          * key=;
787:          * key=#
788:          */
789:         strstrip(key);
790:         strlwc(key, key, len);
791:         value[0]=0 ;
792:         sta = LINE_VALUE ;
793:     } else {
794:         /* Generate syntax error */
795:         sta = LINE_ERROR ;
796:     }
797: 
798:     free(line);
799:     return sta ;
800: }
801: 
802: /*-------------------------------------------------------------------------*/
803: /**
804:   @brief    Parse an ini file and return an allocated dictionary object
805:   @param    in File to read.
806:   @param    ininame Name of the ini file to read (only used for nicer error messages)
807:   @return   Pointer to newly allocated dictionary
808: 
809:   This is the parser for ini files. This function is called, providing
810:   the file to be read. It returns a dictionary object that should not
811:   be accessed directly, but through accessor functions instead.
812: 
813:   The returned dictionary must be freed using iniparser_freedict().
814:  */
815: /*--------------------------------------------------------------------------*/
816: dictionary * iniparser_load_file(FILE * in, const char * ininame)
817: {
818:     char line    [ASCIILINESZ+1] ;
819:     char section [ASCIILINESZ+1] ;
820:     char key     [ASCIILINESZ+1] ;
821:     char tmp     [(ASCIILINESZ * 2) + 2] ;
822:     char val     [ASCIILINESZ+1] ;
823: 
824:     int  last=0 ;
825:     int  len ;
826:     int  lineno=0 ;
827:     int  errs=0;
828:     int  mem_err=0;
829: 
830:     dictionary * dict ;
831: 
832:     dict = dictionary_new(0) ;
833:     if (!dict) {
834:         return NULL ;
835:     }
836: 
837:     memset(line,    0, ASCIILINESZ);
838:     memset(section, 0, ASCIILINESZ);
839:     memset(key,     0, ASCIILINESZ);
840:     memset(val,     0, ASCIILINESZ);
841:     last=0 ;
842: 
843:     while (fgets(line+last, ASCIILINESZ-last, in)!=NULL) {
844:         lineno++ ;
845:         len = (int)strlen(line)-1;
846:         if (len<=0)
847:             continue;
848:         /* Safety check against buffer overflows */
849:         if (line[len]!='\n' && !feof(in)) {
850:             iniparser_error_callback(
851:               "iniparser: input line too long in %s (%d)\n",
852:               ininame,
853:               lineno);
854:             dictionary_del(dict);
855:             return NULL ;
856:         }
857:         /* Get rid of \n and spaces at end of line */
858:         while ((len>=0) &&
859:                 ((line[len]=='\n') || (isspace((unsigned char)line[len])))) {
860:             line[len]=0 ;
861:             len-- ;
862:         }
863:         if (len < 0) { /* Line was entirely \n and/or spaces */
864:             len = 0;
865:         }
866:         /* Detect multi-line */
867:         if (line[len]=='\\') {
868:             /* Multi-line value */
869:             last=len ;
870:             continue ;
871:         } else {
872:             last=0 ;
873:         }
874:         switch (iniparser_line(line, section, key, val)) {
875:             case LINE_EMPTY:
876:             case LINE_COMMENT:
877:             break ;
878: 
879:             case LINE_SECTION:
880:             mem_err = dictionary_set(dict, section, NULL);
881:             break ;
882: 
883:             case LINE_VALUE:
884:             sprintf(tmp, "%s:%s", section, key);
885:             mem_err = dictionary_set(dict, tmp, val);
886:             break ;
887: 
888:             case LINE_ERROR:
889:             iniparser_error_callback(
890:               "iniparser: syntax error in %s (%d):\n-> %s\n",
891:               ininame,
892:               lineno,
893:               line);
894:             errs++ ;
895:             break;
896: 
897:             default:
898:             break ;
899:         }
900:         memset(line, 0, ASCIILINESZ);
901:         last=0;
902:         if (mem_err<0) {
903:             iniparser_error_callback("iniparser: memory allocation failure\n");
904:             break ;
905:         }
906:     }
907:     if (errs) {
908:         dictionary_del(dict);
909:         dict = NULL ;
910:     }
911:     return dict ;
912: }
913: 
914: /*-------------------------------------------------------------------------*/
915: /**
916:   @brief    Parse an ini file and return an allocated dictionary object
917:   @param    ininame Name of the ini file to read.
918:   @return   Pointer to newly allocated dictionary
919: 
920:   This is the parser for ini files. This function is called, providing
921:   the name of the file to be read. It returns a dictionary object that
922:   should not be accessed directly, but through accessor functions
923:   instead.
924: 
925:   The returned dictionary must be freed using iniparser_freedict().
926:  */
927: /*--------------------------------------------------------------------------*/
928: dictionary * iniparser_load(const char * ininame)
929: {
930:     FILE * in ;
931:     dictionary * dict ;
932: 
933:     if ((in=fopen(ininame, "r"))==NULL) {
934:         iniparser_error_callback("iniparser: cannot open %s\n", ininame);
935:         return NULL ;
936:     }
937: 
938:     dict = iniparser_load_file(in, ininame);
939:     fclose(in);
940: 
941:     return dict ;
942: }
